def odd_sum(pieces):
    s = sorted(pieces, reverse=True)
    return sum(s[i] for i in range(0, len(s), 2))

def min_O_greedy(pieces, n_cuts, depth=0):
    '''XY tries many cut strategies and returns min O found.'''
    if n_cuts == 0:
        return odd_sum(pieces)

    pieces = sorted(pieces, reverse=True)
